/**
 * Client-side and server-side upload utilities for ImageKit.
 */

export interface ImageKitUploadResult {
  fileId: string;
  name: string;
  path: string;
  url: string;
  thumbnailUrl?: string;
  size?: number;
  width?: number;
  height?: number;
}

export interface ImageKitUploadOptions {
  folder?: string;
  fileName?: string;
  tags?: string[];
  onProgress?: (percent: number) => void;
}

/**
 * Uploads a file directly from the browser to ImageKit using a temporary signature
 * generated by /api/imagekit/auth.
 *
 * Provides real-time upload progress percentage via XMLHttpRequest.
 */
export async function uploadToImageKitWithProgress(
  file: File | Blob,
  options: ImageKitUploadOptions = {}
): Promise<ImageKitUploadResult> {
  const { folder = "/products", fileName, tags = [], onProgress } = options;

  // 1. Fetch short-lived HMAC authorization parameters from our backend
  onProgress?.(5);
  const authRes = await fetch("/api/imagekit/auth", {
    method: "GET",
    credentials: "include",
    headers: {
      Accept: "application/json",
    },
  });

  if (!authRes.ok) {
    let errMessage = `Failed to get ImageKit upload token (HTTP ${authRes.status})`;
    try {
      const errJson = await authRes.json();
      if (errJson.error) errMessage = errJson.error;
    } catch {
      // Use fallback
    }
    throw new Error(errMessage);
  }

  const authData = await authRes.json();
  if (!authData.signature || !authData.token || !authData.expire || !authData.publicKey) {
    throw new Error(
      authData.error || "Invalid authorization response from ImageKit auth endpoint."
    );
  }

  onProgress?.(15);

  // 2. Prepare clean filename and folder
  const resolvedFileName =
    fileName ||
    (file instanceof File
      ? file.name
      : `image-${Date.now()}.${(file.type || "image/webp").split("/").pop() || "webp"}`);

  const normalizedFolder = folder.startsWith("/") ? folder : `/${folder}`;

  // 3. Assemble multipart FormData for ImageKit REST API
  const formData = new FormData();
  formData.append("file", file, resolvedFileName);
  formData.append("fileName", resolvedFileName);
  formData.append("publicKey", authData.publicKey);
  formData.append("signature", authData.signature);
  formData.append("expire", String(authData.expire));
  formData.append("token", authData.token);
  formData.append("folder", normalizedFolder);
  formData.append("useUniqueFileName", "true");
  if (tags.length > 0) {
    formData.append("tags", tags.join(","));
  }

  // 4. Perform upload via XMLHttpRequest to accurately capture progress
  return new Promise<ImageKitUploadResult>((resolve, reject) => {
    const xhr = new XMLHttpRequest();
    xhr.open("POST", "https://upload.imagekit.io/api/v1/files/upload", true);
    xhr.responseType = "json";

    xhr.upload.onprogress = (event) => {
      if (event.lengthComputable && event.total > 0 && onProgress) {
        // Map upload progress from 15% to 98%
        const rawPercent = (event.loaded / event.total) * 100;
        const mappedPercent = Math.min(98, Math.round(15 + (rawPercent * 0.83)));
        onProgress(mappedPercent);
      }
    };

    xhr.onload = () => {
      if (xhr.status >= 200 && xhr.status < 300) {
        onProgress?.(100);
        const data = xhr.response || JSON.parse(xhr.responseText);
        resolve({
          fileId: data.fileId,
          name: data.name,
          path: data.filePath,
          url: data.url,
          thumbnailUrl: data.thumbnailUrl,
          size: data.size,
          width: data.width,
          height: data.height,
        });
      } else {
        let errorMsg = `ImageKit upload failed with HTTP ${xhr.status}`;
        try {
          const resp = xhr.response || (xhr.responseText ? JSON.parse(xhr.responseText) : null);
          if (resp?.message) errorMsg = resp.message;
          else if (resp?.help) errorMsg = `${resp.message || "Upload error"}: ${resp.help}`;
        } catch {
          // ignore parsing error
        }
        reject(new Error(errorMsg));
      }
    };

    xhr.onerror = () => {
      reject(new Error("Network error occurred during ImageKit file upload. Please check your internet connection."));
    };

    xhr.ontimeout = () => {
      reject(new Error("ImageKit file upload timed out."));
    };

    xhr.send(formData);
  });
}

